<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { storeToRefs } from 'pinia'; import { useSettingsStore } from '../runtime/settings-store'; import SettingsSubnav from '../components/SettingsSubnav.vue'; import SettingsScenarioBar from '../components/SettingsScenarioBar.vue'; import type { SettingsEmployeeDraft } from '../types'; import './settings-views.css'
const store=useSettingsStore(); const { employees, departments, roles, loading, saving, error, scenario, actor }=storeToRefs(store); const editingId=ref<string>(); const form=reactive<SettingsEmployeeDraft>({name:'',account:'',jobNumber:null,departmentId:'',position:null,employeeType:'full-time',roleIds:[],regionId:null,phone:'',email:null,status:'enabled',password:''}); const formError=ref(''); onMounted(()=>store.load()); function edit(item: typeof employees.value[number]) { editingId.value=item.id; Object.assign(form,{...item,password:''}) } function reset(){editingId.value=undefined;Object.assign(form,{name:'',account:'',jobNumber:null,departmentId:departments.value[0]?.id??'',position:null,employeeType:'full-time',roleIds:[],regionId:null,phone:'',email:null,status:'enabled',password:''})} async function submit(){formError.value='';try{const draft={...form,password:form.password||undefined};await store.saveEmployee(draft,editingId.value);reset()}catch(e){formError.value=e instanceof Error?e.message:'保存失败'}}
</script>
<template><section class="settings-page"><header class="settings-header"><div><p class="eyebrow">SET-002 · 员工账号</p><h1>员工账号</h1><p>密码为 fake 元数据；新增和重置后首次登录必须修改。</p></div><SettingsScenarioBar :scenario="scenario" :role="actor.role" @scenario="store.setScenario" @role="store.setRole"/></header><SettingsSubnav/><div v-if="error||formError" class="settings-warning" role="alert">{{error||formError}} <button class="set-button" @click="store.load">重试</button></div><div class="settings-access-grid"><div class="settings-panel"><div class="settings-toolbar"><strong>员工列表</strong><button class="set-button primary" :disabled="actor.role!=='super-admin'" @click="reset">新增员工</button></div><div v-if="loading" class="settings-state">正在加载员工…</div><div v-else class="settings-table-wrap"><table class="settings-table"><thead><tr><th>姓名/账号</th><th>部门</th><th>角色</th><th>状态</th><th>首次登录</th><th>操作</th></tr></thead><tbody><tr v-for="item in employees" :key="item.id"><td>{{item.name}}<small>{{item.account}}</small></td><td>{{departments.find(d=>d.id===item.departmentId)?.name||'—'}}</td><td>{{item.roleIds.map(id=>roles.find(r=>r.id===id)?.name||id).join('、')}}</td><td><span :class="['settings-status',{disabled:item.status==='disabled'}]">{{item.status==='enabled'?'启用':'停用'}}</span></td><td>{{item.mustChangePassword?'是':'否'}}</td><td><button class="set-button" @click="edit(item)">编辑</button><button class="set-button" @click="store.resetEmployeePassword(item.id)">重置密码</button><button class="set-button danger" :disabled="item.status==='disabled'" @click="store.disableEmployee(item.id)">停用</button></td></tr></tbody></table></div></div><form class="settings-panel settings-form" @submit.prevent="submit"><h2 class="settings-form-title">{{editingId?'编辑员工':'新增员工'}}</h2><label>姓名<input v-model.trim="form.name" required></label><label>登录账号<input v-model.trim="form.account" required></label><label>部门<select v-model="form.departmentId" required><option v-for="item in departments" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label>员工类型<select v-model="form.employeeType"><option value="full-time">全职</option><option value="part-time">兼职</option><option value="external">外部</option></select></label><label>联系电话<input v-model.trim="form.phone" required></label><label>邮箱<input v-model.trim="form.email" type="email"></label><label>职位<input v-model.trim="form.position"></label><label>初始密码<input v-model="form.password" type="password" :required="!editingId" placeholder="仅保存 fake 元数据"></label><fieldset class="settings-permissions"><legend>角色</legend><label v-for="role in roles" :key="role.id" class="permission-option"><input v-model="form.roleIds" type="checkbox" :value="role.id" :disabled="role.status==='disabled'">{{role.name}}</label></fieldset><div class="settings-actions"><button type="button" class="set-button" @click="reset">清空</button><button class="set-button primary" :disabled="saving||actor.role!=='super-admin'">{{saving?'保存中…':'保存员工'}}</button></div></form></div></section></template>
